class Handler(SimpleHTTPRequestHandler):
    def log_message(self,*args): return
def server(site):
    h=lambda *a,**k: Handler(*a,directory=str(site),**k); s=ThreadingHTTPServer(("127.0.0.1",0),h); t=threading.Thread(target=s.serve_forever,daemon=True); t.start(); return s,t,f"http://127.0.0.1:{s.server_port}/index.html"
